import torch
import torch_npu
import custom_ops_lib

class ModelNew(torch.nn.Module):
    """
    Optimized 3D transposed convolution using custom AscendC kernel.
    Keeps the same constructor interface as the original module.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # We keep parameters in a PyTorch module to leverage autograd parameter management.
        self.conv_t = torch.nn.ConvTranspose3d(
            in_channels, out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride, padding=padding, dilation=dilation, bias=bias
        )
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.conv_t.weight
        b = self.conv_t.bias if self.conv_t.bias is not None else None
        return custom_ops_lib.conv_transposed_3d_square_input_square_kernel_padded_dilated_strided_custom(
            x, w, b, int(self.stride), int(self.padding), int(self.dilation)
        )
